    expect(parts.quoted).toBe('On Thu, Bob wrote:\n> hi\n> -- \n> Bob');
  });

  it('never hides a body that is entirely quote', () => {
    const quoted = 'On Thu, Ada wrote:\n> can we ship?\n> soon';
