   top border + 1rem vertical padding + the shared row height + the .5rem
}

/* Like a list row: the message fill reaches 6px from both pane edges while its
   text stays on the content inset. The negative margin pulls the stack out of
   the scroller's padding to 6px from each pane edge; the message padding gives
   it back, so text starts at 50px and the right-aligned date ends 24px from the
   right edge. */
.messages {
  list-style: none;
  padding: 0;
  margin: 0 calc(6px - var(--content-inset-end)) 0 calc(6px - var(--content-inset));
}

.message {
  position: relative;
  border-top: 1px solid var(--rule);
  padding: 0.4rem calc(var(--content-inset-end) - 6px) 0.6rem calc(var(--content-inset) - 6px);
  margin-bottom: 0.5rem;
}

/*
 * Current-message treatment: an accent-purple bar (color) plus a non-color
 * indication (a flat raised fill and a primary-color sender) so the focused
 * message never relies on color alone.
 */
.message.message-active {
  background: var(--surface-raised);
  box-shadow: inset 3px 0 0 var(--focus-accent);
}

/* The active bar is the focus indicator for the message toggle: no second ring.
   The fill, bold sender and bar remain; other controls keep the global ring. */
.message.message-active .message-toggle:focus-visible {
  outline: none;
}


/*
 * One line per message: sender, then (collapsed) a clipped body snippet or
 * (expanded) the recipients, then the compact date right-aligned. The full
 * date stays in the title, the screen-reader text and the Details disclosure.
 */
.message-toggle {
  position: relative;
  display: flex;
  align-items: center;
  gap: 0.75rem;
  flex: 1;
  min-width: 0;
  min-height: var(--message-row-height);
  text-align: left;
  font-size: var(--type-body);
  color: var(--text-secondary);
  background: transparent;
  border: 0;
  /* No inline padding: the sender, body, signature and Details share one x. */
  padding: 0.1rem 0;
}

.message-from,
.message-to {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Collapsed senders share one 132px column so the snippets line up. */
.message-toggle[aria-expanded='false'] .message-from {
  flex: 0 0 11em;
}

.message-toggle[aria-expanded='false'] .message-to {
  display: none;
}

.message-snippet {
  flex: 1 1 0;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.message-time {
  flex: none;
  margin-left: auto;
